package envconfig

import (
	"crypto/rand"
	"encoding/hex"
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

// SecretKeys are generated by setup when the file has no value for them.
var SecretKeys = []string{"RELAY_MCP_TOKEN", "RELAY_CREDENTIAL_KEY", "RELAY_TELEGRAM_WEBHOOK_SECRET", "RELAY_EMAIL_WEBHOOK_SECRET"}

// Missing returns the keys that have no non-empty value in the file.
func Missing(path string, keys []string) ([]string, error) {
	values, _, err := read(path)
	if err != nil {
		return nil, err
	}
	var missing []string
	for _, key := range keys {
		if values[key] == "" {
			missing = append(missing, key)
		}
	}
	return missing, nil
}

// Set writes one key atomically with mode 0600 and keeps all other lines.
func Set(path, key, value string) error {
	values, lines, err := read(path)
	if err != nil {
		return err
	}
	if _, err := Parse(key + "=" + value); err != nil {
		return fmt.Errorf("invalid value for %s", key)
	}
	entry := key + "=" + value
	if _, exists := values[key]; exists {
		for i, line := range lines {
			if name, _, ok := strings.Cut(strings.TrimSpace(line), "="); ok && strings.TrimSpace(name) == key {
				lines[i] = entry
			}
		}
	} else {
		lines = append(lines, entry)
	}
	return write(path, strings.Join(lines, "\n")+"\n")
}

// FillSecrets adds each missing secret, preferring a value from the process environment.
func FillSecrets(path string) ([]string, error) {
	missing, err := Missing(path, SecretKeys)
	if err != nil {
		return nil, err
	}
	for _, key := range missing {
		value := os.Getenv(key)
		if value == "" {
			token := make([]byte, 32)
			if _, err := rand.Read(token); err != nil {
				return nil, err
			}
			value = hex.EncodeToString(token)
		}
		if err := Set(path, key, value); err != nil {
			return nil, err
		}
	}
	return missing, nil
}

func read(path string) (map[string]string, []string, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, nil, fmt.Errorf("cannot read project .env")
	}
	values, err := Parse(string(data))
	if err != nil {
		return nil, nil, err
	}
	return values, strings.Split(strings.TrimRight(string(data), "\n"), "\n"), nil
}

func write(path, content string) error {
	file, err := os.CreateTemp(filepath.Dir(path), ".env.tmp-*")
	if err != nil {
		return err
	}
	defer os.Remove(file.Name())
	if err := file.Chmod(0600); err != nil {
		file.Close()
		return err
	}
	if _, err := file.WriteString(content); err != nil {
		file.Close()
		return err
	}
	if err := file.Sync(); err != nil {
		file.Close()
		return err
	}
	if err := file.Close(); err != nil {
		return err
	}
	return os.Rename(file.Name(), path)
}
